with ranked as (select * from (select *, row_number() over (partition by product_id order by quantity desc, id) as row_num from inventory) t where row_num = 1), joined as (select a.*, p.cost from ranked a left join products p on a.product_id = p.id), with_windows as (select id, store_id, product_id, cost, first_value(cost, true) over (partition by store_id order by last_restock, id rows between unbounded preceding and current row) as first_known_cost, sum(quantity) over (partition by product_id order by quantity, id rows between unbounded preceding and current row) as running_quantity from joined), base as (select *, round(cost / first_known_cost, 2) as cost_per_first_known_cost, greatest(running_quantity, first_known_cost) as greatest_running_quantity_first_known_cost from with_windows where first_known_cost between 360 and 510), deduped as (select * from base qualify rank() over (partition by product_id order by cost desc nulls first) = 1), enriched as (select *, ntile(4) over (partition by store_id order by running_quantity, id) as running_quantity_bucket, sum(cost_per_first_known_cost) over w_ordered as running_cost_per_first_known_cost from deduped where cost between 240 and 670 window w_ordered as (partition by product_id order by cost_per_first_known_cost, id rows between unbounded preceding and current row)), with_dims as (select s.id, s.store_id, s.first_known_cost, s.running_quantity, s.cost_per_first_known_cost, s.running_quantity_bucket, b.city from enriched s left join stores b on s.store_id = b.id) select s.region, s.city as store_city, a.city as inventory_city, count(*) as num_rows, min(a.running_quantity_bucket) as min_running_quantity_bucket, max(a.cost_per_first_known_cost) as max_cost_per_first_known_cost from with_dims a left join stores s on a.store_id = s.id group by s.region, s.city, a.city order by num_rows desc nulls last
